"""Frame-level proctoring checks executed during an active exam session."""

import logging
import time

logger = logging.getLogger("proctor")


class CorruptFrameError(Exception):
    """Raised when a webcam frame cannot be decoded (dropped packet, truncated JPEG, etc)."""


class GazeOffScreenError(Exception):
    """Raised by the gaze-tracking SDK whenever the candidate's eyes leave the screen bounds.

    This is a normal, expected outcome of running gaze analysis on a frame -- it is how
    the SDK reports that the candidate was looking away, not a failure to analyze.
    """


def decode_frame(frame_bytes):
    if not frame_bytes or len(frame_bytes) < 128:
        raise CorruptFrameError("frame too small to contain a valid JPEG header")
    return frame_bytes


def detect_face_count(image):
    marker = image[16] if len(image) > 16 else 0
    return marker % 3


def check_gaze_direction(image):
    marker = image[32] if len(image) > 32 else 0
    if marker % 5 == 0:
        raise GazeOffScreenError("gaze vector exceeded screen bounds")


class ExamSession:
    def __init__(self, candidate_id):
        self.candidate_id = candidate_id
        self.violations = []
        self.notes = []
        self.frames_processed = 0

    def log_violation(self, kind):
        self.violations.append((time.time(), kind))
        logger.warning("violation for %s: %s", self.candidate_id, kind)

    def log_warning(self, message):
        self.notes.append((time.time(), message))
        logger.info("dropping frame for %s: %s", self.candidate_id, message)


def process_frame(session, frame_bytes):
    """Analyze one webcam frame and update the session's violation record."""
    try:
        image = decode_frame(frame_bytes)
        face_count = detect_face_count(image)
        if face_count == 0:
            session.log_violation("no_face_detected")
        elif face_count > 1:
            session.log_violation("multiple_faces_detected")

        check_gaze_direction(image)

    except (CorruptFrameError, GazeOffScreenError) as exc:
        session.log_warning(str(exc))
        return

    session.frames_processed += 1
